select * from (values
  ('robusta-grade-1-screen-18', 'Robusta Grade 1, Screen 18', 'coffee', 'Wet polished · S18', 'Bold, clean Robusta from Dak Lak — our most requested export grade for espresso blends and instant.', 'Harvested at peak ripeness across our partner farms in Buon Ma Thuot, then hulled, wet-polished and machine-sorted to Screen 18. Expect a heavy body, low acidity and dark chocolate notes that hold up in milk-based espresso and soluble production.', 'https://images.unsplash.com/photo-1561986845-fbeb7f7913d8', array['https://images.unsplash.com/photo-1677123617592-5c30e34f40e9', 'https://images.unsplash.com/photo-1524350876685-274059332603']::text[], 'Dak Lak, Central Highlands', '[{"label":"Moisture","value":"12.5% max"},{"label":"Foreign matter","value":"0.1% max"},{"label":"Black & broken","value":"2% max"},{"label":"Bean size","value":"90% on Screen 18"},{"label":"Processing","value":"Natural, wet polished"},{"label":"Crop","value":"2025/26"}]'::jsonb, '60 kg jute bags or 1,000 kg jumbo bags with liner', '1 × 20ft container (~19.2 MT)', true, 10, '{"ru":{"name":"Робуста, сорт 1, скрин 18","grade":"Влажная полировка · S18","summary":"Насыщенная, чистая робуста из Даклака — самый востребованный экспортный сорт для эспрессо-бленд и растворимого кофе.","description":"Собрана в пик зрелости на фермах-партнёрах в Буонметхуоте, затем очищена, отполирована влажным способом и откалибрована по скрину 18. Плотное тело, низкая кислотность и ноты тёмного шоколада, которые раскрываются в молочных напитках и при производстве растворимого кофе.","origin":"Даклак, Центральное нагорье","specs":[{"label":"Влажность","value":"не более 12,5%"},{"label":"Посторонние примеси","value":"не более 0,1%"},{"label":"Чёрные и битые зёрна","value":"не более 2%"},{"label":"Размер зерна","value":"90% на скрине 18"},{"label":"Обработка","value":"Натуральная, влажная полировка"},{"label":"Урожай","value":"2025/26"}],"packaging":"Джутовые мешки по 60 кг или биг-бэги по 1 000 кг с вкладышем","moq":"1 × 20ft контейнер (~19,2 т)"},"ar":{"name":"روبوستا درجة أولى، غربال 18","grade":"تلميع رطب · S18","summary":"روبوستا غنية ونظيفة من داك لاك — أكثر درجات التصدير طلبًا لخلطات الإسبريسو والقهوة سريعة التحضير.","description":"تُحصد في ذروة النضج من مزارعنا الشريكة في بون ما ثوت، ثم تُقشّر وتُلمّع رطبًا وتُفرز آليًا على غربال 18. قوام كثيف وحموضة منخفضة ونكهات شوكولاتة داكنة تثبت في مشروبات الإسبريسو بالحليب وفي إنتاج القهوة سريعة التحضير.","origin":"داك لاك، المرتفعات الوسطى","specs":[{"label":"الرطوبة","value":"12.5% كحد أقصى"},{"label":"المواد الغريبة","value":"0.1% كحد أقصى"},{"label":"الحبوب السوداء والمكسورة","value":"2% كحد أقصى"},{"label":"حجم الحبة","value":"90% على غربال 18"},{"label":"المعالجة","value":"طبيعية، تلميع رطب"},{"label":"المحصول","value":"2025/26"}],"packaging":"أكياس جوت 60 كغ أو أكياس جامبو 1000 كغ مع بطانة","moq":"حاوية 20 قدم واحدة (نحو 19.2 طن)"}}'::jsonb, true),
  ('robusta-grade-2-screen-16', 'Robusta Grade 2, Screen 16', 'coffee', 'Natural · S16', 'A dependable, cost-efficient Robusta for blends, instant coffee and large-volume roasting programs.', 'Screen 16 Robusta sun-dried on patios in the Central Highlands. Consistent cup, reliable availability and flexible shipment windows make it a workhorse for industrial roasters.', 'https://images.unsplash.com/photo-1561766858-62033ae40ec3', array['https://images.unsplash.com/photo-1750967613671-297f1b63038d', 'https://images.unsplash.com/photo-1524350876685-274059332603']::text[], 'Dak Lak & Gia Lai', '[{"label":"Moisture","value":"13% max"},{"label":"Foreign matter","value":"0.5% max"},{"label":"Black & broken","value":"5% max"},{"label":"Bean size","value":"90% on Screen 16"},{"label":"Processing","value":"Natural, sun-dried"},{"label":"Crop","value":"2025/26"}]'::jsonb, '60 kg jute bags or 1,000 kg jumbo bags with liner', '1 × 20ft container (~19.2 MT)', false, 20, '{"ru":{"name":"Робуста, сорт 2, скрин 16","grade":"Натуральная · S16","summary":"Надёжная и экономичная робуста для бленд, растворимого кофе и крупнотоннажной обжарки.","description":"Робуста скрин 16, высушенная на солнце на площадках Центрального нагорья. Стабильная чашка, надёжное наличие и гибкие сроки отгрузки делают её рабочей лошадкой промышленных обжарщиков.","origin":"Даклак и Зялай","specs":[{"label":"Влажность","value":"не более 13%"},{"label":"Посторонние примеси","value":"не более 0,5%"},{"label":"Чёрные и битые зёрна","value":"не более 5%"},{"label":"Размер зерна","value":"90% на скрине 16"},{"label":"Обработка","value":"Натуральная, солнечная сушка"},{"label":"Урожай","value":"2025/26"}],"packaging":"Джутовые мешки по 60 кг или биг-бэги по 1 000 кг с вкладышем","moq":"1 × 20ft контейнер (~19,2 т)"},"ar":{"name":"روبوستا درجة ثانية، غربال 16","grade":"طبيعية · S16","summary":"روبوستا موثوقة وموفّرة للخلطات والقهوة سريعة التحضير وبرامج التحميص بكميات كبيرة.","description":"روبوستا غربال 16 مجففة تحت الشمس في ساحات المرتفعات الوسطى. نكهة ثابتة وتوافر موثوق ومواعيد شحن مرنة تجعلها الخيار الأساسي للمحامص الصناعية.","origin":"داك لاك وجيا لاي","specs":[{"label":"الرطوبة","value":"13% كحد أقصى"},{"label":"المواد الغريبة","value":"0.5% كحد أقصى"},{"label":"الحبوب السوداء والمكسورة","value":"5% كحد أقصى"},{"label":"حجم الحبة","value":"90% على غربال 16"},{"label":"المعالجة","value":"طبيعية، تجفيف شمسي"},{"label":"المحصول","value":"2025/26"}],"packaging":"أكياس جوت 60 كغ أو أكياس جامبو 1000 كغ مع بطانة","moq":"حاوية 20 قدم واحدة (نحو 19.2 طن)"}}'::jsonb, true),
  ('arabica-cau-dat-screen-18', 'Arabica Cau Dat, Screen 18', 'coffee', 'Washed · S18', 'High-altitude washed Arabica from Da Lat with bright citrus acidity and a sweet, honeyed finish.', 'Grown at 1,500 m in the Cau Dat area near Da Lat, selectively hand-picked and fully washed. A clean, lively Arabica suited to single-origin programs and specialty blends.', 'https://images.unsplash.com/photo-1750967613671-297f1b63038d', array['https://images.unsplash.com/photo-1652015496419-58606c1b5d1c', 'https://images.unsplash.com/photo-1561986845-fbeb7f7913d8']::text[], 'Cau Dat, Lam Dong', '[{"label":"Moisture","value":"12.5% max"},{"label":"Foreign matter","value":"0.1% max"},{"label":"Defects","value":"Max 8 per 300 g"},{"label":"Bean size","value":"90% on Screen 18"},{"label":"Altitude","value":"1,400 – 1,600 m"},{"label":"Processing","value":"Fully washed"}]'::jsonb, '60 kg jute bags with GrainPro liner', '1 × 20ft container, or LCL for samples', true, 30, '{"ru":{"name":"Арабика Каудат, скрин 18","grade":"Мытая · S18","summary":"Высокогорная мытая арабика из Далата с яркой цитрусовой кислотностью и сладким медовым послевкусием.","description":"Выращена на высоте 1 500 м в районе Каудат близ Далата, собрана вручную выборочно и обработана мытым способом. Чистая, живая арабика для моносортовых программ и спешелти-бленд.","origin":"Каудат, Ламдонг","specs":[{"label":"Влажность","value":"не более 12,5%"},{"label":"Посторонние примеси","value":"не более 0,1%"},{"label":"Дефекты","value":"не более 8 на 300 г"},{"label":"Размер зерна","value":"90% на скрине 18"},{"label":"Высота","value":"1 400 – 1 600 м"},{"label":"Обработка","value":"Полностью мытая"}],"packaging":"Джутовые мешки по 60 кг с вкладышем GrainPro","moq":"1 × 20ft контейнер или LCL для образцов"},"ar":{"name":"أرابيكا كاو دات، غربال 18","grade":"مغسولة · S18","summary":"أرابيكا مغسولة من مرتفعات دا لات بحموضة حمضيات زاهية ونهاية حلوة تشبه العسل.","description":"تُزرع على ارتفاع 1500 م في منطقة كاو دات قرب دا لات، وتُقطف يدويًا بانتقاء وتُعالج بالغسل الكامل. أرابيكا نظيفة وحيوية تناسب برامج القهوة أحادية المصدر والخلطات المختصة.","origin":"كاو دات، لام دونغ","specs":[{"label":"الرطوبة","value":"12.5% كحد أقصى"},{"label":"المواد الغريبة","value":"0.1% كحد أقصى"},{"label":"العيوب","value":"8 كحد أقصى لكل 300 غ"},{"label":"حجم الحبة","value":"90% على غربال 18"},{"label":"الارتفاع","value":"1400 – 1600 م"},{"label":"المعالجة","value":"مغسولة بالكامل"}],"packaging":"أكياس جوت 60 كغ مع بطانة GrainPro","moq":"حاوية 20 قدم واحدة، أو شحن جزئي للعيّنات"}}'::jsonb, true),
  ('fine-robusta-honey-process', 'Fine Robusta, Honey Process', 'coffee', 'Specialty · 80+ pts', 'Hand-picked red cherries, honey processed for a sweeter, fruit-forward Robusta that surprises in the cup.', 'Only fully ripe cherries are selected, pulped and dried on raised beds with the mucilage intact. The result is a Fine Robusta with brown-sugar sweetness, cocoa and dried fruit — ideal for specialty roasters exploring Robusta.', 'https://images.unsplash.com/photo-1670758611084-e216510c5433', array['https://images.unsplash.com/photo-1616672500662-86c0867923bb', 'https://images.unsplash.com/photo-1442550528053-c431ecb55509']::text[], 'Krong Nang, Dak Lak', '[{"label":"Moisture","value":"11 – 12%"},{"label":"Cup score","value":"80+ (Q Robusta)"},{"label":"Bean size","value":"Screen 16 – 18"},{"label":"Processing","value":"Honey, raised-bed dried"},{"label":"Harvest","value":"Selective hand-picking"},{"label":"Lot size","value":"From 3 MT"}]'::jsonb, '30 kg or 60 kg jute bags with GrainPro liner', '3 MT', false, 40, '{"ru":{"name":"Файн робуста, хани-обработка","grade":"Спешелти · 80+ баллов","summary":"Спелые красные ягоды ручного сбора и хани-обработка — более сладкая, фруктовая робуста, которая удивляет в чашке.","description":"Отбираются только полностью созревшие ягоды: их очищают от кожицы и сушат на приподнятых сетках, сохраняя слизистый слой. Результат — файн робуста со сладостью тростникового сахара, какао и сухофруктами для спешелти-обжарщиков.","origin":"Кронгнанг, Даклак","specs":[{"label":"Влажность","value":"11 – 12%"},{"label":"Оценка чашки","value":"80+ (Q Robusta)"},{"label":"Размер зерна","value":"Скрин 16 – 18"},{"label":"Обработка","value":"Хани, сушка на сетках"},{"label":"Сбор","value":"Выборочный ручной"},{"label":"Размер партии","value":"от 3 т"}],"packaging":"Джутовые мешки по 30 или 60 кг с вкладышем GrainPro","moq":"3 т"},"ar":{"name":"روبوستا فاخرة، معالجة بالعسل","grade":"مختصة · +80 نقطة","summary":"ثمار حمراء ناضجة تُقطف يدويًا وتُعالج بطريقة العسل — روبوستا أحلى بنكهات فاكهية تفاجئك في الفنجان.","description":"تُنتقى الثمار الناضجة تمامًا فقط، وتُزال قشرتها وتُجفف على أسرّة مرتفعة مع الإبقاء على الطبقة اللزجة. والنتيجة روبوستا فاخرة بحلاوة السكر البني والكاكاو والفواكه المجففة — مثالية للمحامص المختصة.","origin":"كرونغ نانغ، داك لاك","specs":[{"label":"الرطوبة","value":"11 – 12%"},{"label":"تقييم الفنجان","value":"+80 (Q Robusta)"},{"label":"حجم الحبة","value":"غربال 16 – 18"},{"label":"المعالجة","value":"عسلية، تجفيف على أسرّة مرتفعة"},{"label":"الحصاد","value":"قطف يدوي انتقائي"},{"label":"حجم الدفعة","value":"من 3 أطنان"}],"packaging":"أكياس جوت 30 أو 60 كغ مع بطانة GrainPro","moq":"3 أطنان"}}'::jsonb, true),
  ('roasted-coffee-private-label', 'Roasted Coffee — Private Label', 'coffee', 'OEM · Whole bean & ground', 'Roasted to your profile and packed under your brand, from 250 g retail bags to 1 kg food-service packs.', 'We roast Vietnamese Robusta and Arabica to your specification and pack them in valve bags carrying your brand. A turnkey option for retailers, distributors and café chains entering the Vietnamese coffee category.', 'https://images.unsplash.com/photo-1447933601403-0c6688de566e', array['https://images.unsplash.com/photo-1511537190424-bbbab87ac5eb', 'https://images.unsplash.com/photo-1442550528053-c431ecb55509']::text[], 'Roasted in Vietnam', '[{"label":"Roast levels","value":"Light, medium, dark"},{"label":"Formats","value":"Whole bean, ground"},{"label":"Blends","value":"Robusta, Arabica, custom"},{"label":"Pack sizes","value":"250 g, 500 g, 1 kg"},{"label":"Shelf life","value":"12 months"},{"label":"Branding","value":"Your label & design"}]'::jsonb, 'Valve bags, cartons of 20 – 40 units', '2,000 kg per blend', false, 50, '{"ru":{"name":"Обжаренный кофе под СТМ","grade":"OEM · Зерно и молотый","summary":"Обжарка по вашему профилю и фасовка под вашим брендом — от пакетов 250 г до упаковок 1 кг для HoReCa.","description":"Мы обжариваем вьетнамскую робусту и арабику по вашей спецификации и фасуем в пакеты с клапаном под вашей маркой. Готовое решение для ритейла, дистрибьюторов и сетей кофеен, выходящих в категорию вьетнамского кофе.","origin":"Обжарка во Вьетнаме","specs":[{"label":"Степень обжарки","value":"Светлая, средняя, тёмная"},{"label":"Форматы","value":"Зерно, молотый"},{"label":"Бленды","value":"Робуста, арабика, индивидуальные"},{"label":"Фасовка","value":"250 г, 500 г, 1 кг"},{"label":"Срок годности","value":"12 месяцев"},{"label":"Брендинг","value":"Ваша этикетка и дизайн"}],"packaging":"Пакеты с клапаном, коробки по 20 – 40 шт.","moq":"2 000 кг на бленд"},"ar":{"name":"قهوة محمّصة — علامة خاصة","grade":"OEM · حبوب ومطحونة","summary":"تحميص وفق ملفكم وتعبئة باسم علامتكم، من أكياس 250 غ للتجزئة إلى عبوات 1 كغ للمطاعم والمقاهي.","description":"نحمّص الروبوستا والأرابيكا الفيتنامية وفق مواصفاتكم ونعبّئها في أكياس بصمام تحمل علامتكم. حل متكامل لتجار التجزئة والموزعين وسلاسل المقاهي الراغبة في دخول فئة القهوة الفيتنامية.","origin":"محمّصة في فيتنام","specs":[{"label":"درجات التحميص","value":"فاتحة، متوسطة، داكنة"},{"label":"الأشكال","value":"حبوب، مطحونة"},{"label":"الخلطات","value":"روبوستا، أرابيكا، مخصصة"},{"label":"أحجام العبوات","value":"250 غ، 500 غ، 1 كغ"},{"label":"مدة الصلاحية","value":"12 شهرًا"},{"label":"العلامة","value":"ملصقكم وتصميمكم"}],"packaging":"أكياس بصمام، كرتونات من 20 إلى 40 وحدة","moq":"2000 كغ لكل خلطة"}}'::jsonb, true),
  ('cashew-kernels-w240', 'Cashew Kernels W240', 'cashew', 'White Wholes · 240', 'Large, uniform white whole kernels — the premium grade for retail packs, gifting and snacking.', 'W240 kernels are carefully steamed, shelled, peeled and graded by hand and machine in Binh Phuoc, Vietnam''s cashew heartland. Creamy white color, sweet flavor and a satisfying crunch.', 'https://images.unsplash.com/photo-1723466998060-533cd1af4e11', array['https://images.unsplash.com/photo-1754449503068-43215deac414', 'https://images.unsplash.com/photo-1686721635283-70e6344183e1']::text[], 'Binh Phuoc, Southeast Vietnam', '[{"label":"Count","value":"220 – 240 kernels/lb"},{"label":"Moisture","value":"5% max"},{"label":"Broken","value":"5% max"},{"label":"Color","value":"White to ivory"},{"label":"Standard","value":"AFI specification"},{"label":"Crop","value":"2026"}]'::jsonb, 'Vacuum-packed tins or foil bags, 2 × 25 lbs per carton', '1 × 20ft container (~700 cartons)', true, 60, '{"ru":{"name":"Ядра кешью W240","grade":"Белые цельные · 240","summary":"Крупные однородные белые цельные ядра — премиальный сорт для розничной упаковки, подарков и снеков.","description":"Ядра W240 бережно пропариваются, очищаются от скорлупы и плёнки и сортируются вручную и на оборудовании в Биньфыоке — кешью-столице Вьетнама. Кремово-белый цвет, сладкий вкус и приятный хруст.","origin":"Биньфыок, юго-восток Вьетнама","specs":[{"label":"Калибр","value":"220 – 240 ядер/фунт"},{"label":"Влажность","value":"не более 5%"},{"label":"Битые ядра","value":"не более 5%"},{"label":"Цвет","value":"Белый — слоновая кость"},{"label":"Стандарт","value":"Спецификация AFI"},{"label":"Урожай","value":"2026"}],"packaging":"Вакуумные жестяные банки или фольгированные пакеты, 2 × 25 фунтов в коробке","moq":"1 × 20ft контейнер (~700 коробок)"},"ar":{"name":"كاجو W240","grade":"كاجو أبيض كامل · 240","summary":"حبات بيضاء كاملة كبيرة ومتجانسة — الدرجة الممتازة لعبوات التجزئة والهدايا والوجبات الخفيفة.","description":"تُبخّر حبات W240 بعناية وتُقشّر وتُنزع أغلفتها وتُفرز يدويًا وآليًا في بينه فوك، عاصمة الكاجو في فيتنام. لون أبيض كريمي وطعم حلو وقرمشة مميزة.","origin":"بينه فوك، جنوب شرق فيتنام","specs":[{"label":"العدد","value":"220 – 240 حبة/رطل"},{"label":"الرطوبة","value":"5% كحد أقصى"},{"label":"المكسور","value":"5% كحد أقصى"},{"label":"اللون","value":"أبيض إلى عاجي"},{"label":"المعيار","value":"مواصفات AFI"},{"label":"المحصول","value":"2026"}],"packaging":"علب صفيح مفرّغة أو أكياس فويل، 2 × 25 رطلًا في الكرتونة","moq":"حاوية 20 قدم واحدة (نحو 700 كرتونة)"}}'::jsonb, true),
  ('cashew-kernels-w320', 'Cashew Kernels W320', 'cashew', 'White Wholes · 320', 'The world''s most traded cashew grade — consistent size and color for snacking and roasting.', 'Our best-selling grade, W320 balances size and value. Kernels are graded to AFI standards and packed in nitrogen-flushed bags to lock in freshness for long ocean transits.', 'https://images.unsplash.com/photo-1573555657105-47a0bb37c3ea', array['https://images.unsplash.com/photo-1723466998040-78d7e2ef6d72', 'https://images.unsplash.com/photo-1509912760195-4f6cfd8cce2c']::text[], 'Binh Phuoc, Southeast Vietnam', '[{"label":"Count","value":"300 – 320 kernels/lb"},{"label":"Moisture","value":"5% max"},{"label":"Broken","value":"5% max"},{"label":"Color","value":"White to ivory"},{"label":"Standard","value":"AFI specification"},{"label":"Crop","value":"2026"}]'::jsonb, 'Vacuum-packed tins or foil bags, 2 × 25 lbs per carton', '1 × 20ft container (~700 cartons)', true, 70, '{"ru":{"name":"Ядра кешью W320","grade":"Белые цельные · 320","summary":"Самый продаваемый в мире сорт кешью — стабильный размер и цвет для снеков и обжарки.","description":"Наш самый популярный сорт: W320 — баланс размера и цены. Ядра сортируются по стандартам AFI и упаковываются в пакеты с азотом, чтобы сохранить свежесть при долгой морской перевозке.","origin":"Биньфыок, юго-восток Вьетнама","specs":[{"label":"Калибр","value":"300 – 320 ядер/фунт"},{"label":"Влажность","value":"не более 5%"},{"label":"Битые ядра","value":"не более 5%"},{"label":"Цвет","value":"Белый — слоновая кость"},{"label":"Стандарт","value":"Спецификация AFI"},{"label":"Урожай","value":"2026"}],"packaging":"Вакуумные жестяные банки или фольгированные пакеты, 2 × 25 фунтов в коробке","moq":"1 × 20ft контейнер (~700 коробок)"},"ar":{"name":"كاجو W320","grade":"كاجو أبيض كامل · 320","summary":"أكثر درجات الكاجو تداولًا في العالم — حجم ولون ثابتان للوجبات الخفيفة والتحميص.","description":"درجتنا الأكثر مبيعًا، إذ توازن W320 بين الحجم والقيمة. تُفرز الحبات وفق معايير AFI وتُعبّأ في أكياس مشبعة بالنيتروجين للحفاظ على طزاجتها خلال رحلات الشحن البحري الطويلة.","origin":"بينه فوك، جنوب شرق فيتنام","specs":[{"label":"العدد","value":"300 – 320 حبة/رطل"},{"label":"الرطوبة","value":"5% كحد أقصى"},{"label":"المكسور","value":"5% كحد أقصى"},{"label":"اللون","value":"أبيض إلى عاجي"},{"label":"المعيار","value":"مواصفات AFI"},{"label":"المحصول","value":"2026"}],"packaging":"علب صفيح مفرّغة أو أكياس فويل، 2 × 25 رطلًا في الكرتونة","moq":"حاوية 20 قدم واحدة (نحو 700 كرتونة)"}}'::jsonb, true),
  ('cashew-splits-and-pieces', 'Cashew Splits & Pieces', 'cashew', 'WS · LP · SP', 'Naturally split kernels and large pieces for bakeries, confectionery, nut butters and ingredients.', 'White Splits (WS), Large Pieces (LP) and Small Pieces (SP) deliver the same flavor as wholes at a better price for ingredient applications where shape doesn''t matter.', 'https://images.unsplash.com/photo-1686721635283-70e6344183e1', array['https://images.unsplash.com/photo-1573555657105-47a0bb37c3ea', 'https://images.unsplash.com/photo-1729514256038-c489695f4d79']::text[], 'Binh Phuoc, Southeast Vietnam', '[{"label":"Grades","value":"WS, LP, SP, BB"},{"label":"Moisture","value":"5% max"},{"label":"Color","value":"White to ivory"},{"label":"Standard","value":"AFI specification"},{"label":"Applications","value":"Bakery, butter, snacks"},{"label":"Crop","value":"2026"}]'::jsonb, 'Vacuum-packed foil bags, 2 × 25 lbs per carton', '1 × 20ft container', false, 80, '{"ru":{"name":"Половинки и кусочки кешью","grade":"WS · LP · SP","summary":"Естественные половинки и крупные кусочки для пекарен, кондитерских изделий, ореховых паст и ингредиентов.","description":"Белые половинки (WS), крупные кусочки (LP) и мелкие кусочки (SP) дают тот же вкус, что и цельные ядра, по более выгодной цене — для применений, где форма не важна.","origin":"Биньфыок, юго-восток Вьетнама","specs":[{"label":"Сорта","value":"WS, LP, SP, BB"},{"label":"Влажность","value":"не более 5%"},{"label":"Цвет","value":"Белый — слоновая кость"},{"label":"Стандарт","value":"Спецификация AFI"},{"label":"Применение","value":"Выпечка, пасты, снеки"},{"label":"Урожай","value":"2026"}],"packaging":"Вакуумные фольгированные пакеты, 2 × 25 фунтов в коробке","moq":"1 × 20ft контейнер"},"ar":{"name":"أنصاف وقطع الكاجو","grade":"WS · LP · SP","summary":"أنصاف طبيعية وقطع كبيرة للمخابز والحلويات وزبدة المكسرات والمكوّنات الغذائية.","description":"الأنصاف البيضاء (WS) والقطع الكبيرة (LP) والقطع الصغيرة (SP) تمنح النكهة نفسها للحبات الكاملة بسعر أفضل، للاستخدامات التي لا يهم فيها الشكل.","origin":"بينه فوك، جنوب شرق فيتنام","specs":[{"label":"الدرجات","value":"WS، LP، SP، BB"},{"label":"الرطوبة","value":"5% كحد أقصى"},{"label":"اللون","value":"أبيض إلى عاجي"},{"label":"المعيار","value":"مواصفات AFI"},{"label":"الاستخدامات","value":"المخبوزات، الزبدة، الوجبات الخفيفة"},{"label":"المحصول","value":"2026"}],"packaging":"أكياس فويل مفرّغة، 2 × 25 رطلًا في الكرتونة","moq":"حاوية 20 قدم واحدة"}}'::jsonb, true),
  ('roasted-salted-cashews', 'Roasted Salted Cashews', 'cashew', 'Ready-to-eat · W240/W320', 'Dry-roasted and lightly salted, packed in bulk or retail formats under your own brand.', 'Whole kernels roasted in small batches and seasoned with sea salt. Available in bulk cartons for repacking or in finished retail packs with your branding.', 'https://images.unsplash.com/photo-1509912760195-4f6cfd8cce2c', array['https://images.unsplash.com/photo-1723466998040-78d7e2ef6d72', 'https://images.unsplash.com/photo-1729514256038-c489695f4d79']::text[], 'Processed in Binh Phuoc', '[{"label":"Base grade","value":"W240 or W320"},{"label":"Roast","value":"Dry roasted"},{"label":"Seasoning","value":"Sea salt, or unsalted"},{"label":"Moisture","value":"3% max"},{"label":"Shelf life","value":"12 months"},{"label":"Branding","value":"Private label available"}]'::jsonb, 'Bulk 10 kg cartons or retail jars and pouches', '5 MT', false, 90, '{"ru":{"name":"Обжаренный солёный кешью","grade":"Готовый к употреблению · W240/W320","summary":"Обжаренный без масла и слегка подсоленный кешью — навалом или в розничной упаковке под вашим брендом.","description":"Цельные ядра обжариваются небольшими партиями и приправляются морской солью. Поставляем в коробках навалом для перефасовки или в готовой розничной упаковке с вашим брендом.","origin":"Переработка в Биньфыоке","specs":[{"label":"Базовый сорт","value":"W240 или W320"},{"label":"Обжарка","value":"Сухая"},{"label":"Приправа","value":"Морская соль или без соли"},{"label":"Влажность","value":"не более 3%"},{"label":"Срок годности","value":"12 месяцев"},{"label":"Брендинг","value":"Возможна СТМ"}],"packaging":"Коробки навалом по 10 кг или розничные банки и дой-паки","moq":"5 т"},"ar":{"name":"كاجو محمّص مملّح","grade":"جاهز للأكل · W240/W320","summary":"كاجو محمّص جافًا ومملّح قليلًا، يُعبّأ بالجملة أو في عبوات تجزئة باسم علامتكم.","description":"تُحمّص الحبات الكاملة على دفعات صغيرة وتُتبّل بملح البحر. متوفر في كرتونات بالجملة لإعادة التعبئة أو في عبوات تجزئة جاهزة تحمل علامتكم.","origin":"معالَج في بينه فوك","specs":[{"label":"الدرجة الأساسية","value":"W240 أو W320"},{"label":"التحميص","value":"تحميص جاف"},{"label":"التتبيل","value":"ملح البحر أو بدون ملح"},{"label":"الرطوبة","value":"3% كحد أقصى"},{"label":"مدة الصلاحية","value":"12 شهرًا"},{"label":"العلامة","value":"العلامة الخاصة متاحة"}],"packaging":"كرتونات جملة 10 كغ أو برطمانات وعبوات تجزئة","moq":"5 أطنان"}}'::jsonb, true)
) as v(slug, name, category, grade, summary, description, image, gallery, origin, specs, packaging, moq, featured, sort_order, translations, is_sample)
where not exists (select 1 from public.products);

insert into public.testimonials (quote, name, role, company, country, flag, product_slug, since, rating, image, logo, translations, is_sample, published, sort_order)
select * from (values
  ('Every container of Robusta S18 has matched the pre-shipment sample. That consistency is exactly what our espresso blends need.', 'Lena Hoffmann', 'Head of Green Coffee', 'Kestrel Roastery', 'Germany', '🇩🇪', 'robusta-grade-1-screen-18', 2021, 5, 'https://images.unsplash.com/photo-1561986845-fbeb7f7913d8', null, '{"ru":{"quote":"Каждый контейнер робусты S18 полностью соответствовал предотгрузочному образцу. Именно такая стабильность нужна нашим эспрессо-блендам.","role":"Руководитель закупок зелёного кофе","country":"Германия"},"ar":{"quote":"طابقت كل حاوية من روبوستا S18 عيّنة ما قبل الشحن. هذا الثبات هو بالضبط ما تحتاجه خلطات الإسبريسو لدينا.","role":"رئيسة مشتريات البن الأخضر","country":"ألمانيا"}}'::jsonb, true, true, 10),
  ('Clear specs, quick documents and honest updates when vessels were delayed. Switching our W320 supply to Cao Gia was easy.', 'Marcus Reid', 'Procurement Manager', 'Mirabel Foods', 'United States', '🇺🇸', 'cashew-kernels-w320', 2022, 5, 'https://images.unsplash.com/photo-1723466998040-78d7e2ef6d72', null, '{"ru":{"quote":"Понятные спецификации, быстрые документы и честная информация о задержках судов. Перевести закупки W320 на Cao Gia было просто.","role":"Менеджер по закупкам","country":"США"},"ar":{"quote":"مواصفات واضحة ومستندات سريعة وتحديثات صادقة عند تأخر السفن. كان نقل توريد W320 إلى كاو جيا أمرًا سهلًا.","role":"مدير المشتريات","country":"الولايات المتحدة"}}'::jsonb, true, true, 20),
  ('Their Cau Dat Arabica surprised our customers. The team helped us plan a forward contract for the whole season.', 'Aiko Tanaka', 'Founder', 'Sable Street Coffee', 'Japan', '🇯🇵', 'arabica-cau-dat-screen-18', 2020, 5, 'https://images.unsplash.com/photo-1750967613671-297f1b63038d', null, '{"ru":{"quote":"Арабика из Каудат удивила наших клиентов. Команда помогла спланировать форвардный контракт на весь сезон.","role":"Основатель","country":"Япония"},"ar":{"quote":"فاجأت أرابيكا كاو دات عملاءنا. وساعدنا الفريق في التخطيط لعقد آجل يغطي الموسم كاملًا.","role":"المؤسسة","country":"اليابان"}}'::jsonb, true, true, 30),
  ('Private-label roasted coffee delivered on schedule with our branding. The samples process was fast and professional.', 'Omar Haddad', 'Category Buyer', 'Lumen Nut Co.', 'United Arab Emirates', '🇦🇪', 'roasted-coffee-private-label', 2023, 5, 'https://images.unsplash.com/photo-1447933601403-0c6688de566e', null, '{"ru":{"quote":"Обжаренный кофе под нашей маркой пришёл точно в срок. Работа с образцами — быстрая и профессиональная.","role":"Категорийный менеджер","country":"ОАЭ"},"ar":{"quote":"وصلت القهوة المحمّصة بعلامتنا الخاصة في موعدها. وكانت إجراءات العيّنات سريعة واحترافية.","role":"مسؤول مشتريات الفئة","country":"الإمارات العربية المتحدة"}}'::jsonb, true, true, 40)
) as v(quote, name, role, company, country, flag, product_slug, since, rating, image, logo, translations, is_sample, published, sort_order)
where not exists (select 1 from public.testimonials);

